/* 出错时告诉人「卡在哪一句」——bf-12 排查模式 A 时，旧 ev() 静默 return undefined，
   调用方 JSON.parse(undefined) 只抛一句「"undefined" is not valid JSON」，看不出是哪一步。 */
let lastExpr = "(还没跑任何表达式)";
async function ev(expr) {
  lastExpr = String(expr).replace(/\s+/g, " ").slice(0, 140);
  const r = await send("Runtime.evaluate", { expression: expr, returnByValue: true, awaitPromise: true });
  if (r && r.exceptionDetails) return "EXC:" + ((r.exceptionDetails.exception || {}).description || r.exceptionDetails.text || "");
  /* CDP 明确报错 / 干脆没返回 result → 显式抛，绝不静默变 undefined */
  if (r && r.error) throw new Error("CDP 拒绝了表达式（" + (r.error.message || JSON.stringify(r.error)) + "）：" + lastExpr);
  if (!r || !r.result) throw new Error("CDP 没返回结果（响应 " + JSON.stringify(r).slice(0, 200) + "）：" + lastExpr);
  return r.result.result.value;
}
